//! 🎟️ The same Original Source retains every borrowed-output receiving phase and its consuming decoder ledger.
use super::*;
use semio_framework_job::{OriginalTurnFailure,StepContext};
use semio_framework_job_native_decode::{OriginalNativeDecodeSource,OriginalNativeDecodePolicy,OriginalNativeDecodeIssued,OriginalNativeDecodeOutcome};
use semio_framework_value_native_owned::native_decoding::{NativeReceivingEffect,NativeReceivingEffectFailure,NativeReceivingEffectPhase,NativeReceivingEffectPoll};
pub type OriginalJsonOutputOutcome=OriginalNativeDecodeOutcome<RetainedCloneStep,OriginalReceivingPrimary>;
pub enum OriginalJsonOutputClose{Producer(Option<OriginalNativeDecodeOutcome<RetainedCloneStep>>),Source(RetainedCloneStep)}
/// 🧳️ Admission creates no parser or allocation before the containing native payload belongs to its actual Source.
pub struct OriginalJsonOutputSource<T:NativeReceive<DslValue>+Sync>{decode:OriginalNativeDecodeSource,receiver:Option<OriginalJsonOutputReceiving<T>>,limits:JsonReadLimits,frame:Option<NativeReceivingEffect<ValueError>>}
fn narrow(work:u128)->u64{u64::try_from(work).unwrap_or(u64::MAX)}
fn issued(poll:RetainedWorkPoll<RetainedCloneStep,OriginalReceivingPrimary>,grant:RetainedCloneGrant)->OriginalNativeDecodeIssued<RetainedCloneStep,OriginalReceivingPrimary>{
 let turn=match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{work:0}=>RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0},RetainedWorkPoll::Pending{work}=>RetainedWorkOutcome{result:Err(invalid().into()),work}};
 let progress=turn.result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.progress);
 OriginalNativeDecodeIssued{value:turn.result,grant,progress,work:narrow(turn.work)}
}
fn issued_close(value:Result<RetainedCloneStep,ValueError>,work:u128,grant:RetainedCloneGrant)->OriginalNativeDecodeIssued<RetainedCloneStep>{
 let progress=value.as_ref().map(|step|step.progress()).unwrap_or_else(ValueError::retained_progress);
 OriginalNativeDecodeIssued{value,grant,progress,work:narrow(work)}
}
fn effect_error(failure:NativeReceivingEffectFailure<ValueError>)->ValueError{let progress=failure.retained_progress();failure.child.or(failure.producer_refusal).or(failure.work_refusal).unwrap_or_else(||refused(failure.receiving)).with_retained_progress(progress)}
fn settled(poll:OriginalRetirementPoll)->RetainedWorkOutcome<RetainedCloneStep,ValueError>{match RetirementPollExit::settled(poll){Ok(turn)=>RetainedWorkOutcome{result:turn.result.map_err(OriginalRetirementFailure::into_value_error),work:turn.work},Err(_)=>RetainedWorkOutcome{result:Err(invalid()),work:0}}}
fn finished(polled:NativeReceivingEffectPoll<ValueError>,work:&mut u128)->Result<RetainedCloneStep,ValueError>{match polled{NativeReceivingEffectPoll::Pending{work:0}=>Ok(RetainedCloneStep::Progress(Default::default())),NativeReceivingEffectPoll::Pending{work:pending}=>{*work=pending;Err(invalid())},NativeReceivingEffectPoll::Complete(turn)=>{*work=turn.work;turn.result.map_err(effect_error)}}}
impl<T:NativeReceive<DslValue>+Sync> OriginalJsonOutputSource<T>{
 pub const fn new(policy:OriginalNativeDecodePolicy,limits:JsonReadLimits)->Self{Self{decode:OriginalNativeDecodeSource::empty(policy),receiver:None,limits,frame:None}}
 pub fn receive_step(&mut self,input:&[u8],cx:&mut StepContext<'_>)->Result<Option<OriginalJsonOutputOutcome>,OriginalTurnFailure>{let receiver=&mut self.receiver;let limits=self.limits;let fuel=cx.fuel_remaining();self.decode.receive_step(cx,|control,grant|{if let Some(receiver)=receiver.as_mut(){return issued(receiver.advance(input,control,grant.maximum_copy_bytes,fuel,grant),grant)}if !retained_clone_grant_admits(grant,OriginalJsonOutputReceiving::<T>::constructor_demand()){return issued(done(Ok(RetainedCloneStep::Progress(Default::default())),0),grant)}match OriginalJsonOutputReceiving::admit(input,limits,control,grant){Ok((owner,progress))=>{*receiver=Some(owner);issued(done(Ok(RetainedCloneStep::Progress(progress)),1),grant)},Err(error)=>issued(done(Err(error.into()),0),grant)}})}
 pub fn take_step(&mut self,output:&mut Option<T>,cx:&mut StepContext<'_>)->Result<Option<OriginalJsonOutputOutcome>,OriginalTurnFailure>{let receiver=&mut self.receiver;self.decode.receive_step(cx,|control,grant|{let Some(receiver)=receiver.as_mut()else{return issued(done(Err(invalid().into()),0),grant)};let turn=match control.with_effect(grant,1,|_,effect|receiver.take_into(output,effect)){Ok(Some(turn))=>RetainedWorkOutcome{result:turn.result.map_err(Into::into),work:turn.work},Ok(None)=>RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0},Err(error)=>RetainedWorkOutcome{result:Err(error.into()),work:0}};issued(RetainedWorkPoll::Complete(turn),grant)})}
 pub fn ready(&self)->bool{self.receiver.as_ref().is_some_and(OriginalJsonOutputReceiving::ready)}
 pub fn receiver(&self)->Option<&OriginalJsonOutputReceiving<T>>{self.receiver.as_ref()}
 pub fn close_owned_step<U:semio_framework_value::retirement::RetireOwned>(&mut self,owner:&mut semio_framework_value::retirement::controlled::ControlledRetirement<U>,cx:&mut StepContext<'_>)->Result<Option<OriginalNativeDecodeOutcome<RetainedCloneStep>>,OriginalTurnFailure>{let frame=self.frame.get_or_insert_with(Default::default);self.decode.close_producer_step(cx,|control,grant|{let mut work=0;let value=control.with_retirement(grant,|retirement|{let body=grant.maximum_copy_bytes;let demand=owner.next_demand(body)?;if !retained_clone_grant_admits(grant,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}let quote=owner.next_computational_work(body)?;let polled=retirement.receive_effect(demand,quote,frame,|_,effect|settled(owner.step(effect)))?;finished(polled,&mut work)});issued_close(value,work,grant)})}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<OriginalJsonOutputClose,OriginalTurnFailure>{if let Some(receiver)=self.receiver.as_mut(){if !receiver.terminal_is_empty(){receiver.begin_close();let frame=self.frame.get_or_insert_with(Default::default);return self.decode.close_producer_step(cx,|control,grant|{let mut work=0;let value=control.with_retirement(grant,|retirement|{let body=grant.maximum_copy_bytes;let demand=receiver.close_demands(body)?;if !retained_clone_grant_admits(grant,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}let quote=receiver.close_work_demand(body)?;let polled=retirement.receive_effect(demand,quote,frame,|control,effect|settled(receiver.close_step(control,effect)))?;finished(polled,&mut work)});issued_close(value,work,grant)}).map(OriginalJsonOutputClose::Producer)}}self.decode.close_step(cx).map(OriginalJsonOutputClose::Source)}
 pub fn terminal_is_empty(&self)->bool{self.decode.terminal_is_empty()&&self.receiver.as_ref().is_none_or(OriginalJsonOutputReceiving::terminal_is_empty)&&self.frame.as_ref().is_none_or(|frame|frame.phase()==NativeReceivingEffectPhase::Empty)}
}
